                   (ctxt->input->end - ctxt->input->cur < 2 * INPUT_CHUNK)) \
        xmlParserShrink(ctxt)

#define GROW if ((ctxt->progressive == 0) &&                            \
                 (ctxt->input->end - ctxt->input->cur < INPUT_CHUNK))   \
        xmlParserGrow(ctxt)

